const PRIVATE_HEADERS = {
    'Cache-Control': 'private, no-store, max-age=0',
    'X-Content-Type-Options': 'nosniff'
};

export async function handlePrivateSurge(request) {
    const url = new URL(request.url);
    const entry = PAYLOADS.get(url.pathname);
    if (!entry) {
        return null;
    }

    if (request.method !== 'GET' && request.method !== 'HEAD') {
        return new Response('Method Not Allowed', {
            status: 405,
            headers: {
                ...PRIVATE_HEADERS,
                Allow: 'GET, HEAD',
                'Content-Type': 'text/plain; charset=utf-8'
            }
        });
    }

    const token = url.searchParams.get('token');
    if (!token || token.length < 32) {
        return notFound();
    }

    try {
        const body = await decrypt(entry.payload, token);
        return new Response(request.method === 'HEAD' ? null : body, {
            status: 200,
            headers: {
                ...PRIVATE_HEADERS,
                'Content-Type': entry.contentType
            }
        });
    } catch {
        // Return the same response for missing and invalid tokens to avoid leaking route details.
        return notFound();
    }
}

async function decrypt(payload, token) {
    const [ivPart, ciphertextPart] = payload.split('.');
    if (!ivPart || !ciphertextPart) {
        throw new Error('Invalid encrypted payload');
    }

    const keyMaterial = await webcrypto.subtle.digest(
        'SHA-256',
        new TextEncoder().encode(token)
    );
    const key = await webcrypto.subtle.importKey(
        'raw',
        keyMaterial,
        { name: 'AES-GCM' },
        false,
        ['decrypt']
    );
    const plaintext = await webcrypto.subtle.decrypt(
        {
            name: 'AES-GCM',
            iv: fromBase64Url(ivPart)
        },
        key,
        fromBase64Url(ciphertextPart)
    );
    return new TextDecoder().decode(plaintext);
}

function fromBase64Url(value) {
    return Buffer.from(value, 'base64url');
}

function notFound() {
    return new Response('Not Found', {
        status: 404,
        headers: {
            ...PRIVATE_HEADERS,
            'Content-Type': 'text/plain; charset=utf-8'
        }
    });
}
